import{_ as a,o as n,c as t,a3 as p}from"./chunks/framework.Dz5Q8p4s.js";const g=JSON.parse('{"title":"Pixel Motion as Universal Representation for Robot Control","description":"","frontmatter":{"title":"Pixel Motion as Universal Representation for Robot Control","arxiv":"2505.07817","date":"2025-05-12","authors":"Kanchana Ranasinghe, Xiang Li, E-Ro Nguyen, Cristina Mata, Jongwoo Park, Michael S Ryoo","categories":"cs.RO, cs.CV","topics":"具身智能, 像素运动表示, 双系统策略","outline":[2,2]},"headers":[],"relativePath":"papers/2505.07817.md","filePath":"papers/2505.07817.md","lastUpdated":null}'),l={name:"papers/2505.07817.md"};function e(i,s,m,r,c,o){return n(),t("div",null,[...s[0]||(s[0]=[p('<h1 id="pixel-motion-as-universal-representation-for-robot-control" tabindex="-1">Pixel Motion as Universal Representation for Robot Control <a class="header-anchor" href="#pixel-motion-as-universal-representation-for-robot-control" aria-label="Permalink to &quot;Pixel Motion as Universal Representation for Robot Control&quot;">​</a></h1><table tabindex="0"><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td><strong>arXiv</strong></td><td><a href="https://arxiv.org/abs/2505.07817" target="_blank" rel="noreferrer">2505.07817</a></td></tr><tr><td><strong>提交日期</strong></td><td>2025-05-12</td></tr><tr><td><strong>作者</strong></td><td>Kanchana Ranasinghe, Xiang Li, E-Ro Nguyen, Cristina Mata, Jongwoo Park, Michael S Ryoo</td></tr><tr><td><strong>分类</strong></td><td>cs.RO, cs.CV</td></tr><tr><td><strong>一句话</strong></td><td>用图像扩散模型从单帧观测 + 语言直接生成稠密光流作为跨本体的中间表示，再由一个轻量映射把光流转成动作，从而让任意视频-字幕数据都能训练机器人策略的上层。</td></tr></tbody></table><blockquote><p><strong>所属教程</strong>：<a href="/notes/tutorials/embodied-ai-general">通用具身智能</a></p></blockquote><div class="tip custom-block"><p class="custom-block-title">版本说明</p><p>arXiv abs 页给出的 HTML 版本是 <strong>v2</strong>（2025-08-28 修订，v1 为 2025-05-12），本文按 v2 全文撰写。方法名为 <strong>LangToMo</strong>，本站论文索引里的 &quot;Pixel Motion&quot; 取自 arXiv 标题前缀，非编号错误。</p></div><h2 id="§-1-—-研究问题与重要性" tabindex="-1">§ 1 — 研究问题与重要性 <a class="header-anchor" href="#§-1-—-研究问题与重要性" aria-label="Permalink to &quot;§ 1 — 研究问题与重要性&quot;">​</a></h2><p>机器人学习的两个诉求长期打架：一是要一个跨本体、跨视角、跨任务都成立的通用表示，二是要能用没有动作标注的视频-语言数据。前者通常靠共享的动作空间或统一的 token 化解决，后者通常靠&quot;预测未来 RGB 帧&quot;（UniPi、AVDC、SuSIE 那一路）解决。但预测 RGB 有个结构性代价：RGB 里编码了大量与动作无关的信息——机械臂的颜色、人手的肤色、背景光照——模型必须先学会渲染这些，才谈得上表达运动。</p><p>本文主张换一个中间量：<strong>稠密像素运动（即光流）</strong>。它可以用 RAFT 从任意视频里免费算出来，天然抹掉外观、只保留运动；而且它保留了图像的 2D 网格结构，与&quot;稀疏点轨迹&quot;那一路（ATM、Im2Flow2Act、Track2Act）相比能同时覆盖物体运动与机械臂自身运动。如果这条表示真的通用，那么&quot;人类演示视频&quot;和&quot;机器人演示视频&quot;就可以进同一个训练目标，数据来源的天花板被整体抬高一层。</p><h2 id="§-2-—-前人工作与不足" tabindex="-1">§ 2 — 前人工作与不足 <a class="header-anchor" href="#§-2-—-前人工作与不足" aria-label="Permalink to &quot;§ 2 — 前人工作与不足&quot;">​</a></h2><p><strong>预测未来帧一路</strong>：UniPi 用文本引导视频生成再反解动作，AVDC 生成下一帧 RGB 并用手工映射转动作，SuSIE 用图像编辑扩散生成子目标。它们的共同问题是 RGB 空间的 embodiment gap 太大——本文附录 J 直接量化了这一点：40 条人类演示与 40 条机器人演示的 RGB 像素值分布的对称 KL 散度是 0.7881，而像素运动分布的对称 KL 只有 0.0199。</p><p><strong>稀疏点轨迹一路</strong>：ATM、Im2Flow2Act、Track2Act 预测若干关键点的轨迹。这些点通常被限制在感兴趣物体上，忽略机械臂本身的运动（论文 Figure 2 用一个杯子的例子说明这一点），而且把 2D 结构压成 1D 坐标序列。</p><p><strong>从图像对估计光流一路</strong>：这是一个良定问题（RAFT 之类），但需要未来帧。本文要求的是从<strong>单帧 + 语言</strong>预测未来 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord mathnormal" style="margin-right:0.0315em;">k</span></span></span></span> 步的光流，这是一个一对多的问题——同一张图配同一句指令可以对应多条合法轨迹。</p><p><strong>双系统 VLA 一路</strong>：同期的 <a href="/notes/papers/2505.03912">OpenHelix</a> 系统梳理了这条线，并指出现有做法里上游传给下游的隐向量往往退化成指令摘要、对画面变化不敏感。LangToMo 恰好从另一个方向绕开了这个问题——它的中间量是一张显式的、可视化的运动场，无法退化成常量。</p><h2 id="§-3-—-重建作者的思考路径" tabindex="-1">§ 3 — 重建作者的思考路径 <a class="header-anchor" href="#§-3-—-重建作者的思考路径" aria-label="Permalink to &quot;§ 3 — 重建作者的思考路径&quot;">​</a></h2><p>只用本文之前的知识可以这样推：想让上层策略从互联网视频里学，就必须选一个<strong>能从原始视频免费导出</strong>的监督目标。候选只有几类：未来帧（RGB）、点轨迹、光流、分割掩码。分割掩码需要额外模型且语义化程度高；点轨迹需要选点策略；未来帧包含太多无关信息。光流是唯一一个既能免费算（RAFT）、又不含外观、还保留 2D 结构的量。</p><p>接着的问题是：从单帧预测光流是多模态的，回归会塌成均值。扩散模型是处理多模态输出分布的标准答案，而且既然目标是一个 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7778em;vertical-align:-0.0833em;"></span><span class="mord mathnormal">h</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6667em;vertical-align:-0.0833em;"></span><span class="mord mathnormal" style="margin-right:0.0269em;">w</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">2</span></span></span></span> 的 2D 张量，直接改一个 2D 条件 U-Net 的输入输出通道数就行——不需要新架构。</p><p>最后一步：光流不是动作。但光流是<strong>可解释</strong>的——如果知道机械臂在图像里的位置和场景深度，就能把像素位移反算成 3D 位移。这意味着下层可以是手工规则（无监督设定），也可以是一个用少量示范训的小网络。这两种实例化正好覆盖了&quot;完全无动作标注&quot;和&quot;少量动作标注&quot;两种场景。</p><h2 id="§-4-—-核心-intuition" tabindex="-1">§ 4 — 核心 Intuition <a class="header-anchor" href="#§-4-—-核心-intuition" aria-label="Permalink to &quot;§ 4 — 核心 Intuition&quot;">​</a></h2><p>让先前方法失效的是<strong>外观</strong>：机器人和人类做同一个动作时像素长得完全不一样，所以在 RGB 空间学到的策略无法在两者之间迁移。让本方法奏效的是把外观整个除掉——光流只记录&quot;哪块像素往哪边走了多少&quot;，人手和夹爪抓同一只橡皮鸭时的光流场几乎重合。于是&quot;用什么身体做&quot;这件事被推给了下层的映射函数，上层只需要学&quot;该发生什么运动&quot;。</p><h2 id="§-5-—-具体方法与完整-pipeline" tabindex="-1">§ 5 — 具体方法与完整 Pipeline <a class="header-anchor" href="#§-5-—-具体方法与完整-pipeline" aria-label="Permalink to &quot;§ 5 — 具体方法与完整 Pipeline&quot;">​</a></h2><p>以真机任务&quot;Pick up the rubber duck and place on the bowl&quot;为例：</p><ol><li><strong>System 2 输入</strong>：当前帧 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5944em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord"><span class="mord"><span class="mord boldsymbol">x</span></span></span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span>（3 通道）、上一段像素运动 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8247em;vertical-align:-0.3802em;"></span><span class="mord"><span class="mord"><span class="mord"><span class="mord boldsymbol" style="margin-right:0.037em;">y</span></span></span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.242em;"><span style="top:-2.4559em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">i</span><span class="mbin mtight">−</span><span class="mord mathnormal mtight" style="margin-right:0.0315em;">k</span><span class="mpunct mtight">,</span><span class="mord mathnormal mtight">i</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.3802em;"><span></span></span></span></span></span></span></span></span></span>（2 通道）、指令经 Universal Sentence Encoder 编码得到的固定长度向量 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4444em;"></span><span class="mord"><span class="mord"><span class="mord boldsymbol">c</span></span></span></span></span></span>。</li><li><strong>架构</strong>：一个 2D 条件 U-Net，输入头改成 7 通道（2 通道待去噪的光流 + 2 通道历史光流 + 3 通道当前图像），输出头改成 2 通道。图像与历史光流这 5 个条件通道<strong>不参与加噪调度</strong>；文本走默认的 cross-attention 条件。</li><li><strong>推理</strong>：25 步 DDIM 从噪声生成 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1.0881em;vertical-align:-0.3802em;"></span><span class="mord"><span class="mord accent"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.7079em;"><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord"><span class="mord boldsymbol" style="margin-right:0.037em;">y</span></span></span></span><span style="top:-3.0134em;"><span class="pstrut" style="height:3em;"></span><span class="accent-body" style="left:-0.25em;"><span class="mord">^</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.1944em;"><span></span></span></span></span></span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.242em;"><span style="top:-2.4559em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">i</span><span class="mpunct mtight">,</span><span class="mord mathnormal mtight">i</span><span class="mbin mtight">+</span><span class="mord mathnormal mtight" style="margin-right:0.0315em;">k</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.3802em;"><span></span></span></span></span></span></span></span></span></span>。首步的历史光流置零；后续步的历史光流由&quot;过去帧-当前帧&quot;实测得到。</li><li><strong>System 1</strong>：真机上用单平面假设（桌面）+ 相机标定，把机械臂中心点的预测像素位移投影到平面上得到位置增量；仿真上按 AVDC 的做法用分割掩码与深度图把像素运动转成 3D 方向。学习版（LTM-S）则把 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.9023em;vertical-align:-0.1944em;"></span><span class="mord accent"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.7079em;"><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord"><span class="mord boldsymbol" style="margin-right:0.037em;">y</span></span></span></span><span style="top:-3.0134em;"><span class="pstrut" style="height:3em;"></span><span class="accent-body" style="left:-0.25em;"><span class="mord">^</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.1944em;"><span></span></span></span></span></span></span></span></span>、<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5944em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord"><span class="mord"><span class="mord boldsymbol">x</span></span></span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span>、<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7305em;vertical-align:-0.2861em;"></span><span class="mord"><span class="mord"><span class="mord"><span class="mord boldsymbol">x</span></span></span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">i</span><span class="mbin mtight">+</span><span class="mord mathnormal mtight" style="margin-right:0.0572em;">j</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span></span></span></span> 通道拼接送进一个 ViT-T 回归动作向量，每任务只用 20 条示范训练。</li><li><strong>频率</strong>：System 2 每被调用一次，System 1 跑 10 个控制步（手工版则跑到收敛）。</li></ol><p>训练数据：System 2 在 OpenX 的 7 个子集（fractal、taco_play、language_table、stanford_hydra、ucsd_pick_place、cmu_pickup、utaustin_mutex，横跨 Google Robot / Franka / xArm 三种本体、3–20 Hz 五种控制频率）上预训 30 万步（8×A100），再在下游任务上微调 10 万步。真机每个任务收 10 条机器人演示（RD）与 50 条人类演示（HD），<strong>微调只用视频-字幕对、不用任何动作真值</strong>。</p><h2 id="§-6-—-核心数学推导" tabindex="-1">§ 6 — 核心数学推导 <a class="header-anchor" href="#§-6-—-核心数学推导" aria-label="Permalink to &quot;§ 6 — 核心数学推导&quot;">​</a></h2><p>把语言到运动的映射写成</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1.0881em;vertical-align:-0.3802em;"></span><span class="mord"><span class="mord accent"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.7079em;"><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord"><span class="mord boldsymbol" style="margin-right:0.037em;">y</span></span></span></span><span style="top:-3.0134em;"><span class="pstrut" style="height:3em;"></span><span class="accent-body" style="left:-0.25em;"><span class="mord">^</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.1944em;"><span></span></span></span></span></span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.242em;"><span style="top:-2.4559em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">i</span><span class="mpunct mtight">,</span><span class="mord mathnormal mtight">i</span><span class="mbin mtight">+</span><span class="mord mathnormal mtight" style="margin-right:0.0315em;">k</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.3802em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1.2302em;vertical-align:-0.3802em;"></span><span class="mord mathcal" style="margin-right:0.0278em;">D</span><span class="mopen"><span class="delimsizing size1">(</span></span><span class="mord"><span class="mord"><span class="mord"><span class="mord boldsymbol">x</span></span></span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace"> </span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord"><span class="mord"><span class="mord boldsymbol" style="margin-right:0.037em;">y</span></span></span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.242em;"><span style="top:-2.4559em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">i</span><span class="mbin mtight">−</span><span class="mord mathnormal mtight" style="margin-right:0.0315em;">k</span><span class="mpunct mtight">,</span><span class="mord mathnormal mtight">i</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.3802em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace"> </span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord"><span class="mord boldsymbol">c</span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">∣</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1.2em;vertical-align:-0.35em;"></span><span class="mord mathnormal" style="margin-right:0.0278em;">θ</span><span class="mclose"><span class="delimsizing size1">)</span></span></span></span></span></span></p><p>目标是 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1.1302em;vertical-align:-0.3802em;"></span><span class="mop">ar<span style="margin-right:0.0139em;">g</span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mop"><span class="mop">min</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0278em;">θ</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">∥</span><span class="mord"><span class="mord"><span class="mord"><span class="mord boldsymbol" style="margin-right:0.037em;">y</span></span></span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.242em;"><span style="top:-2.4559em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">i</span><span class="mpunct mtight">,</span><span class="mord mathnormal mtight">i</span><span class="mbin mtight">+</span><span class="mord mathnormal mtight" style="margin-right:0.0315em;">k</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.3802em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathcal" style="margin-right:0.0278em;">D</span><span class="mopen">(</span><span class="mord">⋅</span><span class="mclose">)</span><span class="mord"><span class="mord">∥</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">2</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span>。这里有一个容易被略过但很关键的点：<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8247em;vertical-align:-0.3802em;"></span><span class="mord"><span class="mord"><span class="mord"><span class="mord boldsymbol" style="margin-right:0.037em;">y</span></span></span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.242em;"><span style="top:-2.4559em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">i</span><span class="mpunct mtight">,</span><span class="mord mathnormal mtight">i</span><span class="mbin mtight">+</span><span class="mord mathnormal mtight" style="margin-right:0.0315em;">k</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.3802em;"><span></span></span></span></span></span></span></span></span></span> 是从 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6528em;vertical-align:-0.2083em;"></span><span class="mord"><span class="mord"><span class="mord"><span class="mord boldsymbol">x</span></span></span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord"><span class="mord"><span class="mord boldsymbol">x</span></span></span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">i</span><span class="mbin mtight">+</span><span class="mord mathnormal mtight" style="margin-right:0.0315em;">k</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2083em;"><span></span></span></span></span></span></span></span></span></span> 用 RAFT 算出来的，而 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6528em;vertical-align:-0.2083em;"></span><span class="mord"><span class="mord"><span class="mord"><span class="mord boldsymbol">x</span></span></span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">i</span><span class="mbin mtight">+</span><span class="mord mathnormal mtight" style="margin-right:0.0315em;">k</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2083em;"><span></span></span></span></span></span></span></span></span></span> 在推理时不可见。所以这不是光流估计问题，而是<strong>给定当前状态与语言意图，预测未来 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord mathnormal" style="margin-right:0.0315em;">k</span></span></span></span> 步的运动场</strong>——一个真正的一对多映射，因此必须用生成模型而不是回归。消融里&quot;用自编码器替代扩散&quot;直接从 57.7% 掉到 16.2%，正是这个论断的实证。</p><p>下层映射写成</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.994em;vertical-align:-0.2861em;"></span><span class="mord"><span class="mord accent"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.7079em;"><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord"><span class="mord boldsymbol">a</span></span></span></span><span style="top:-3.0134em;"><span class="pstrut" style="height:3em;"></span><span class="accent-body" style="left:-0.25em;"><span class="mord">^</span></span></span></span></span></span></span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">i</span><span class="mbin mtight">+</span><span class="mord mathnormal mtight" style="margin-right:0.0572em;">j</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1.2302em;vertical-align:-0.3802em;"></span><span class="mord mathcal" style="margin-right:0.0993em;">F</span><span class="mopen"><span class="delimsizing size1">(</span></span><span class="mord"><span class="mord accent"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.7079em;"><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord"><span class="mord boldsymbol" style="margin-right:0.037em;">y</span></span></span></span><span style="top:-3.0134em;"><span class="pstrut" style="height:3em;"></span><span class="accent-body" style="left:-0.25em;"><span class="mord">^</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.1944em;"><span></span></span></span></span></span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.242em;"><span style="top:-2.4559em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">i</span><span class="mpunct mtight">,</span><span class="mord mathnormal mtight">i</span><span class="mbin mtight">+</span><span class="mord mathnormal mtight" style="margin-right:0.0315em;">k</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.3802em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace"> </span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord"><span class="mord"><span class="mord boldsymbol">x</span></span></span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace"> </span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord"><span class="mord"><span class="mord boldsymbol">x</span></span></span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">i</span><span class="mbin mtight">+</span><span class="mord mathnormal mtight" style="margin-right:0.0572em;">j</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span><span class="mclose"><span class="delimsizing size1">)</span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:2em;"></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.0572em;">j</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">∈</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">[</span><span class="mord">0</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.0315em;">k</span><span class="mclose">]</span></span></span></span></span></p><p><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6595em;"></span><span class="mord mathnormal">i</span></span></span></span> 是 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord mathnormal" style="margin-right:0.0315em;">k</span></span></span></span> 的倍数。这条式子把频率分离写清楚了：<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.9023em;vertical-align:-0.1944em;"></span><span class="mord accent"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.7079em;"><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord"><span class="mord boldsymbol" style="margin-right:0.037em;">y</span></span></span></span><span style="top:-3.0134em;"><span class="pstrut" style="height:3em;"></span><span class="accent-body" style="left:-0.25em;"><span class="mord">^</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.1944em;"><span></span></span></span></span></span></span></span></span> 每 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord mathnormal" style="margin-right:0.0315em;">k</span></span></span></span> 步更新一次，而 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7079em;"></span><span class="mord accent"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.7079em;"><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord"><span class="mord boldsymbol">a</span></span></span></span><span style="top:-3.0134em;"><span class="pstrut" style="height:3em;"></span><span class="accent-body" style="left:-0.25em;"><span class="mord">^</span></span></span></span></span></span></span></span></span></span> 每步都算——同一个运动目标被复用 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord mathnormal" style="margin-right:0.0315em;">k</span></span></span></span> 次，中间靠实时观测 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7305em;vertical-align:-0.2861em;"></span><span class="mord"><span class="mord"><span class="mord"><span class="mord boldsymbol">x</span></span></span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">i</span><span class="mbin mtight">+</span><span class="mord mathnormal mtight" style="margin-right:0.0572em;">j</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span></span></span></span> 做闭环。这与同期 OpenHelix 诊断的&quot;上游隐向量与时间无关&quot;形成对照：这里的 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.9023em;vertical-align:-0.1944em;"></span><span class="mord accent"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.7079em;"><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord"><span class="mord boldsymbol" style="margin-right:0.037em;">y</span></span></span></span><span style="top:-3.0134em;"><span class="pstrut" style="height:3em;"></span><span class="accent-body" style="left:-0.25em;"><span class="mord">^</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.1944em;"><span></span></span></span></span></span></span></span></span> 显式地是一个有向运动场，<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathcal" style="margin-right:0.0993em;">F</span></span></span></span> 必须逐步消耗它。</p><h2 id="§-7-—-实验设计与结论" tabindex="-1">§ 7 — 实验设计与结论 <a class="header-anchor" href="#§-7-—-实验设计与结论" aria-label="Permalink to &quot;§ 7 — 实验设计与结论&quot;">​</a></h2><p><strong>问题一：不做任何下游微调能否直接部署？</strong> 真机 4 类任务、每类 20 次随机化试验，纯预训练的 LTM-H 拿 33.8%，高于 GPT-4o 的 18.8% 与 LLaRA 的 22.5%，而 RT-2 风格与 AVDC 均为 0。</p><p><strong>问题二：人类演示有用吗？</strong> 微调后 LTM-H：只用 HD 36.3、只用 RD 68.8、RD+HD 71.3；AVDC 用 RD 只有 7.5，用 RD+HD 直接崩到 0。方向上支持&quot;光流比 RGB 更 embodiment-agnostic&quot;，但<strong>RD → RD+HD 的净收益只有 +2.5 个百分点</strong>，在 4 任务×20 次=80 次试验上等于 2 次成功之差。</p><p><strong>问题三：与最接近的先前工作比？</strong> MetaWorld 11 任务、3 个相机位姿、每位姿 25 次随机化。LTM-H 52.1、LTM-S 57.7、ATM 52.0、AVDC(Default) 43.1、AVDC(Flow) 13.7、Diffusion Policy 24.1。作者强调的 &quot;+9.0%&quot; 是 LTM-H 对 AVDC 的差（两者用同一套手工映射，是干净对照）。但要看清：<strong>LTM-H 相对 ATM 只领先 0.1</strong>，逐任务上 LTM-H 在 faucet-close（41.3 vs 53.3）、faucet-open（33.3 vs 62.7）、hammer（4.3 vs 8.0）上都输。真正拉开差距的是 LTM-S，而 LTM-S 的 System 1 额外用了每任务 20 条动作标注示范。另有一条值得注意：AVDC(PT) 42.9 与 AVDC(Default) 43.1 几乎相同，说明 OpenX 预训练对 RGB 预测路线<strong>完全无效</strong>，这是全文最支持核心论点的一格。</p><p><strong>问题四：各组件贡献？</strong> 完整 57.7 → 去预训练 53.1 → 再去历史光流 50.2 → 再去语言 39.7 → 只留语言去掉图像 5.6。另一组：无扩散 16.2、cross-attention 替代通道拼接 15.8、System 1/2 同频 48.7、只留学习版 System 1（绕过 System 2）3.2。</p><p><strong>附加评测</strong>：CALVIN ABC→D 上 LTM-S 平均长度 3.81（100% ABC），低于 VPP 4.33 与 DreamVLA 4.44（作者说明两者预训练数据与模型更大）；10% ABC 下 3.38 高于 VPP 3.25。iThor 导航上 LTM-H 31.9 vs AVDC 31.3——基本持平，且 Bathroom 一格两者同为 36.7。</p><h2 id="§-8-—-take-aways" tabindex="-1">§ 8 — Take-aways <a class="header-anchor" href="#§-8-—-take-aways" aria-label="Permalink to &quot;§ 8 — Take-aways&quot;">​</a></h2><p><strong>5 句话版</strong>：LangToMo 用稠密光流替代 RGB 作为语言与动作之间的中间表示，因为光流可以从任意视频免费导出且几乎不含外观信息。上层是一个把光流当作 2D 图像来生成的条件扩散 U-Net，条件通过通道拼接注入；下层是手工规则或用 20 条示范训的 ViT-T。MetaWorld 上 LTM-S 57.7% 超过 ATM 52.0 与 AVDC 43.1，真机零样本 33.8%。最有说服力的一格是 OpenX 预训练对本方法值 +4.6 而对 RGB 预测的 AVDC 值 −0.2。局限是仍需为每个新本体设计映射函数、只有 2D 无深度、且扩散推理开销大。</p><p><strong>3 句话版</strong>：把&quot;预测未来帧&quot;换成&quot;预测未来光流&quot;，就把跨本体的外观差异从表示里除掉了。上层用图像扩散生成运动场、下层用轻量映射转动作，两者频率解耦、独立训练。收益的关键证据是同样的互联网预训练只对光流路线有效。</p><p><strong>1 句话版</strong>：光流是能从任意视频免费获得、且人和机器人共用的动作表示。</p><h2 id="§-9-—-最脆弱的假设" tabindex="-1">§ 9 — 最脆弱的假设 <a class="header-anchor" href="#§-9-—-最脆弱的假设" aria-label="Permalink to &quot;§ 9 — 最脆弱的假设&quot;">​</a></h2><p>最要命的一条是：<strong>&quot;上层通用、下层特化&quot;这个划分里，被推给下层的那部分是廉价的</strong>。论文的 Limitations 自己承认 System 1 对每个新本体都要重新手工设计或重新训练。但问题比&quot;成本&quot;更深——真机手工映射依赖单平面假设加相机标定，仿真手工映射依赖<strong>真值分割掩码与真值深度图</strong>（沿用 AVDC 的设定）。也就是说，MetaWorld 上 52.1% 的 LTM-H 成绩是在拥有特权信息的条件下取得的。</p><p>如果去掉这些特权信息，光流的&quot;可解释性&quot;就不再免费：把 2D 像素位移变成 3D 动作本质上需要知道每个像素的深度和哪些像素属于机械臂，而这两件事恰恰是感知里的难题。论文提供的证据是学习版 System 1（LTM-S）不需要分割与深度、只需要 20 条示范就更强（57.7），这确实缓解了这条批评；但 LTM-S 也就不再是&quot;无监督控制&quot;，而且 20 条示范/任务的规模并不比直接行为克隆省多少——同表的 BC 基线用了 15,216 帧动作对。</p><p>第二条脆弱之处：Limitations 明写&quot;训练只用固定相机视频、不处理自我运动&quot;，而附录 B.3 却在有自我运动的 iThor 上做了评测（且只赢 AVDC 0.6 分）。这说明该表示对相机运动的鲁棒性尚未被建立。</p><h2 id="§-10-—-最小复现实验" tabindex="-1">§ 10 — 最小复现实验 <a class="header-anchor" href="#§-10-—-最小复现实验" aria-label="Permalink to &quot;§ 10 — 最小复现实验&quot;">​</a></h2><p>一周可做、且不需要真机：在 MetaWorld 上复现三条对照——(a) 完整 LTM-S，(b) 去掉语言条件的 LTM-S，(c) 把 System 2 的输出替换成<strong>用真值未来帧算出的 RAFT 光流</strong>（oracle 上界）。前两条论文已给（57.7 与 39.7），第三条缺失且最有信息量。</p><p>判据：若 (c) 远高于 (a)，说明瓶颈在运动预测而非映射，后续投入应该放在生成模型；若 (c) 与 (a) 接近，说明 System 1 的映射误差已是主导项，&quot;通用表示&quot;的叙事需要让位给&quot;本体适配&quot;的工程问题。这条实验只需推理 + 一次 RAFT 计算，成本极低，却能直接判定该框架未来的投入方向。</p><h2 id="§-11-—-最强反例设计" tabindex="-1">§ 11 — 最强反例设计 <a class="header-anchor" href="#§-11-—-最强反例设计" aria-label="Permalink to &quot;§ 11 — 最强反例设计&quot;">​</a></h2><p>最强的替代解释来自消融表本身：<strong>去掉语言条件后 MetaWorld 仍有 39.7%</strong>，几乎追平完整的 AVDC（43.1），远超 Diffusion Policy（24.1）与 BC-Scratch（16.2）。MetaWorld 的每个环境里通常只有一个可交互物体，任务由环境本身决定，语言几乎是冗余的。这意味着本文在 MetaWorld 上测到的大部分能力可能是&quot;从单帧预测该场景里最可能发生的运动&quot;，而不是&quot;把语言映射成运动&quot;——而后者才是标题里 &quot;LangToMo&quot; 的卖点。</p><p>判决性反例这样设计：构造一个<strong>同一初始画面对应两个互斥指令</strong>的评测集（论文附录 B.1 已有定性示例：&quot;pick up the green duck&quot; vs &quot;pick up the orange duck&quot;），每对指令下各跑 25 次，报告&quot;执行了正确那个物体&quot;的比例而非任务成功率。如果这个比例接近 50%（随机），则语言通道是惰性的，MetaWorld 的 57.7% 需要重新归因。作者只给了两张定性图，没有给这个数字。</p><p>第二个攻击点是效应量与统计功效。真机 RD → RD+HD 的 +2.5%、iThor 上的 +0.6%、以及 LTM-H 对 ATM 的 +0.1%，全部落在各自评测规模（80 次 / 每类 60 次 / 每任务 75 次）的单次成功分辨率附近。论文没有报告任何标准差或多次运行，因此这几条结论应当被读作&quot;未被证伪&quot;而非&quot;已被证实&quot;。</p><p>另需指出一处内部不一致：正文 Table 5 里完整模型是 57.7，而附录 I 讨论同一组消融时写&quot;去掉预训练从 <strong>53.6%</strong> 掉到 53.1%&quot;——53.6 这个数字在正文表中不存在，两处对不上。</p><h2 id="§-12-—-follow-up-research-idea" tabindex="-1">§ 12 — Follow-up Research Idea <a class="header-anchor" href="#§-12-—-follow-up-research-idea" aria-label="Permalink to &quot;§ 12 — Follow-up Research Idea&quot;">​</a></h2><p>本文把&quot;通用性&quot;押在了表示的<strong>不变性</strong>上：光流对外观不变，所以能跨本体。但它同时付出了代价——光流对深度与遮挡完全无知，作者自己把 3D 扩展列为未来工作。直接做&quot;3D 场景流&quot;是显然的增量方向，不值得做。</p><p>更有意思的重新 framing 是：<strong>不要预设中间表示，而是把它当作一个可学习的、带不变性约束的量</strong>。具体地，把中间表示 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4444em;"></span><span class="mord"><span class="mord"><span class="mord boldsymbol" style="margin-right:0.0421em;">z</span></span></span></span></span></span> 定义为一个 2D 网格上的向量场，并加两个目标：(i) 它必须足以让下游映射复原动作（充分性），(ii) 它在&quot;同一动作的人类演示与机器人演示&quot;之间的分布距离要小（不变性，恰好可以用本文附录 J 的对称 KL 作为目标而不只是事后指标）。光流是这个优化问题的一个<strong>手工解</strong>；学出来的解可能自动包含一部分深度或接触信息，而这些正是光流缺的。</p><p>可借鉴的相邻领域工具是域不变表示学习（DANN / IRM）与视频自监督里的运动-外观解耦。第一个实验不需要机器人：在本文已有的 40 条人类 + 40 条机器人配对演示上，比较三种中间表示（RAFT 光流、学出的不变向量场、RGB 隐编码）在 (i) 对称 KL 与 (ii) 用 20 条示范线性探针预测动作的 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8141em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0077em;">R</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8141em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">2</span></span></span></span></span></span></span></span></span></span></span> 这两个轴上的位置。如果学出的表示能在保持低 KL 的同时显著提高动作可解码性，就说明&quot;光流&quot;只是这条帕累托前沿上的一个点，而不是终点。</p>',55)])])}const d=a(l,[["render",e]]);export{g as __pageData,d as default};
